import sys, json
from typing import List

class Solution:
    def pancakeSort(self, arr: List[int]) -> List[int]:
        ans = []
        for size in range(len(arr), 1, -1):
            idx = arr.index(size)
            if idx == size - 1:
                continue
            if idx != 0:
                arr[:idx + 1] = reversed(arr[:idx + 1])
                ans.append(idx + 1)
            arr[:size] = reversed(arr[:size])
            ans.append(size)
        return ans

