class Solution {
public:
    vector<int> pancakeSort(vector<int>& arr) {
        vector<int> ans;
        for (int size = (int)arr.size(); size > 1; --size) {
            int idx = find(arr.begin(), arr.end(), size) - arr.begin();
            if (idx == size - 1) continue;

            if (idx != 0) {
                reverse(arr.begin(), arr.begin() + idx + 1);
                ans.push_back(idx + 1);
            }
            reverse(arr.begin(), arr.begin() + size);
            ans.push_back(size);
        }
        return ans;
    }
